/* SPDX-License-Identifier: MIT
 * ISA fields: Imagination MIT pvr_rogue_pds_{encode,defs}.h.
 * Capture06 first task and both main VS streams equal these generated bytes.
 * The code fetches stride*input0+base with DDMAD, dispatches C0 USC via DOUTU
 * then HALTs. No captured address or instruction template is retained.
 */
#include "native_triangle_pds.h"
static void put(uint8_t *p,unsigned n,uint32_t v)
{ for(unsigned j=0;j<4;j++)p[4*n+j]=(uint8_t)(v>>(8*j)); }
static int build(struct a04_m111_triangle_vertex_pds *out,
    uint64_t usc,uint64_t vertex,uint32_t components,uint32_t stride,uint32_t temps)
{
    struct a04_m111_triangle_vertex_pds made={{0},{0}};
    const uint64_t ub=UINT64_C(0xba00000000);
    if(!out || usc<ub || usc-ub>=0x40000000u || (usc&3u) ||
       vertex<4096 || vertex>=(UINT64_C(1)<<40) || (vertex&3u) ||
       (components!=2 && components!=3 && components!=4 && components!=8) ||
       stride!=components*4u || temps>128u ||
       vertex>(UINT64_C(1)<<40)-3u*stride)return 1;
    put(made.data,0,(uint32_t)(usc-ub));
    /* DOUTU TEMPS: bit35, allocation unit4 DWORD. */
    put(made.data,1,((temps+3u)/4u)<<3);
    put(made.data,2,stride);
    put(made.data,4,(uint32_t)vertex);put(made.data,5,(uint32_t)(vertex>>32));
    put(made.data,6,(1u<<31)|components); /* last DMA, unified store */
    put(made.code,0,(0xeu<<28)|(2u<<18)|(2u<<6)|3u);
    put(made.code,1,(0xfu<<28)|(1u<<27)|(1u<<26)|2u);
    put(made.code,2,(0xdu<<28)|(3u<<24)); /* special opcode HALT */
    *out=made;return 0;
}

int a04_m111_build_triangle_vertex_pds(struct a04_m111_triangle_vertex_pds *out,
    uint64_t usc,uint64_t vertex,uint32_t components,uint32_t stride)
{
    if(components!=2 && components!=3 && components!=4)return 1;
    return build(out,usc,vertex,components,stride,0);
}
int a04_m111_build_linked_vertex_pds(struct a04_m111_triangle_vertex_pds *out,
    uint64_t usc,uint64_t vertex,uint32_t temps)
{ return build(out,usc,vertex,8,32,temps); }

/* ABI4: actual validated compiler temp allocation, same bounded real VB fetch. */
int a04_m111_build_program_vertex_pds(struct a04_m111_triangle_vertex_pds *out,uint64_t usc,uint64_t vertex,uint32_t temps)
{return build(out,usc,vertex,4,16,temps);}

/* Source: pvr_pds_inst_encode_dout / DOUTD common-store fields and the
 * vertex-program contract in pvr_rogue_pds_defs.h. The CB DMA has no LAST:
 * the following real vertex DDMAD is the final DMA before USC dispatch. */
int a04_m111_build_uniform_vertex_pds(struct a04_m111_uniform_vertex_pds *out,
 uint64_t usc,uint64_t vertex,uint32_t temps,uint64_t constants,uint32_t shareds)
{
 struct a04_m111_uniform_vertex_pds made={{0},{0}};
 struct a04_m111_triangle_vertex_pds base;
 if(!out||!shareds||shareds>16||(shareds&3u)||constants<4096||
    constants>=(UINT64_C(1)<<40)||(constants&15u)||
    constants>(UINT64_C(1)<<40)-shareds*4u||
    (constants<vertex+48&&vertex<constants+shareds*4u)||
    build(&base,usc,vertex,4,16,temps))return 1;
 for(unsigned i=0;i<32;i++)made.data[i]=base.data[i];
 put(made.data,8,(uint32_t)constants);put(made.data,9,(uint32_t)(constants>>32));
 put(made.data,10,(1u<<28)|shareds); /* AO0, common-store, 32bit, no LAST */
 /* DOUTD src0=C64[4], src1=C32[10], no END. No guessed register bits. */
 put(made.code,0,(0xfu<<28)|(10u<<16)|(4u<<8));
 for(unsigned i=0;i<12;i++)made.code[4+i]=base.code[i];
 *out=made;return 0;
}
